data.transform:
(
  $calculateEstimatedTime := function(
    $standardRate,
    $quantity,
    $setupRate,
    $productionTypeId,
    $transitTimeAfter,
    $transitTimeBefore,
    $leadTime
  ) {
    (
      $standardRate := $coalesce([$standardRate, 0]);
      $setupRate := $coalesce([$setupRate, 0]);
      $quantity := $coalesce([$quantity, 0]);
      $transitTimeAfter := $coalesce([$transitTimeAfter, 0]);
      $transitTimeBefore := $coalesce([$transitTimeBefore, 0]);
      $leadTime := $coalesce([$leadTime, 0]);
      $internalTime := $standardRate = 0 or $quantity = 0
        ? 0
        : ($quantity / $standardRate) * 3600000 + $setupRate;
      $outsideProcessingTime := $leadTime + $transitTimeBefore
        + $transitTimeAfter;
      $productionTypeId = "Outside Processor"
        ? $outsideProcessingTime
        : $internalTime
    )};

  $calculateUsage := function($boms, $usageType){(
    $calculatedUsages := $boms.(
			$outputRate := $coalesce([
        unitPerCycle,
        componentProductStrategyProcess.unitPerCycle,
        1
      ]);

      $usage := $lookup($, $usageType);
      $coalesce([$usage, standardUsage, 1]) * $outputRate;

    );

    $count($calculatedUsages) > 0? $sum($calculatedUsages) : 0;

  )};

  $backwardsSchedule := function($dueDate, $records){(
    $reduce(
      $records^(>order),
      function($acc, $crr, $i){(
        $startingEndDate := $moment($i = 0? $dueDate : $acc[$i -1].scheduledStartAt);


        $latestStartAt := $startingEndDate.clone().subtract($crr.estimatedTime, "ms" );

        $newValue := $merge([
          $crr,
          { "scheduledStartAt": $latestStartAt.format(), "scheduledFinishAt": $startingEndDate.format()}
        ]);

        $append($acc, [$omit($newValue, "order")]);

      )},
      []
    )~>$reverse
  )};


  $workorder := workOrder.edges.node;
  $isNilOrEmpty($workorder.promiseAt)? $throw("A due date is required to schedule a workorder.");
  $isNilOrEmpty($workorder.workOrderProcesses.edges)? $throw("Workorder requires processes.");
  $payload := $workorder.workOrderProcesses.edges.node.(

    $coProducts := productStrategyProcess.coproductBoms.edges.node;
    $byProducts := productStrategyProcess.byproductBoms.edges.node;

    $distributionGroupPayload := {
        "id": id,
        "balanceQuantity": quantity,
        "cycleTime": $coalesce([cycleTime, 0]),
        "estimatedTime": $calculateEstimatedTime(standardRate, quantity, setupRate, productionTypeId, transitTimeAfter, transitTimeBefore, leadTime),
        "percentComplete": 0,
        "producedQuantity": 0,
        "productionOperators": $coalesce([productionOperators, 1]),
        "quotedRate": $coalesce([quotedRate,0]), 
        "requiredQuantity": quantity,
        "scrappedQuantity": 0,
        "setupOperators": $coalesce([setupOperators, 0]),
        "setupRate": $coalesce([setupRate, 0]),
        "standardRate": $coalesce([standardRate, 0]),
        "allowDistributionUnload": false,
        "parallelPositions": $count($byProducts) > 0 or $count($coProducts) > 0,
        "requireParallelOutput": true,
        "sequential": false,
        "singleSetupRate": true,
        "static": $count($coProducts) != 0 or $count($byProducts) != 0,
        "groupId": code,
        "workOrderProcessDistributionStatusId": "New",
        "workcenterId":workcenterId,
        "order": order
      };

    $materialUsage := $calculateUsage($coProducts, "standardUsage") + $calculateUsage($byProducts, "standardUsage");
    $machineUsage := $calculateUsage($coProducts, "machineUsage") + $calculateUsage($byProducts, "machineUsage");
    $laborUsage := $calculateUsage($coProducts, "laborUsage") + $calculateUsage($byProducts, "laborUsage");

    $distributionPayload := $distributionGroupPayload.(
     $merge([
					$omit(
						$,
						[
							"id",
							"static",
							"groupId",
							"static",
							"allowDistributionUnload",
							"parallelPositions",
							"requireParallelOutput",
							"sequential",
							"singleSetupRate"
						]
					),
					{
						"id": id,
						"dispatchSequence": 0,
						"materialUsage": $materialUsage > 1 ? 0 : (1 - $materialUsage),
						"machineUsage": $machineUsage > 1 ? 0 : (1 - $machineUsage),
						"laborUsage": $laborUsage > 1 ? 0 : (1 - $laborUsage),
						"leadingProduct": true,
						"distributionGroupId": id,
						"workOrderProcessId": id,
						"workOrderId": $workorder.id,
						"virtual": $materialUsage >= 1
					}
				])  
    );

    {
      "distributionGroupPayload": $distributionGroupPayload,
      "distributionPayload": $distributionPayload
    }
  );

  $scheduledDistributions := $backwardsSchedule($workorder.promiseAt,$payload.distributionPayload); 

  {
    "workorderPayload":[
      {
        "where": {"id": $workorder.id  },
        "update":{ 
          "scheduledStartAt": $scheduledDistributions[0].scheduledStartAt, 
          "scheduledFinishAt": $scheduledDistributions[-1].scheduledFinishAt
          }
      }
    ],
    "distributionGroupPayload":  $backwardsSchedule($workorder.promiseAt,$payload.distributionGroupPayload).{"create": $},
    "distributionPayload":  $scheduledDistributions.{"create": $}
  }
)

data.mutation:
mutation (
  $distributionGroupPayload: [WorkOrderProcessDistributionGroupCreatePayloadInput!]!, 
  $distributionPayload: [WorkOrderProcessDistributionCreatePayloadInput!]!,
  $workorderPayload: [WorkOrderUpdatePayloadInput!]!
){
  createWorkOrderProcessDistributionGroup(payload: $distributionGroupPayload){ id }
  createWorkOrderProcessDistribution(payload: $distributionPayload){ id  workOrderProcessId}
  updateWorkOrder(payload: $workorderPayload){ id }
}

